Note on ZTS509: `workflow.call` must be at step depth 0 inside `run()`, never inside `step()`. So the structure:

```ts
import { run, step } from "zttp:durable";
import { call } from "zttp:workflow";

export function handler(req: Request): Proof<Response, ...> {
  const key = req.headers.get("idempotency-key");
  if (key === undefined) {
    return Response.json({ error: "missing idempotency-key" }, { status: 400 });
  }
  return run(key, () => {
    const reservation = step("reserve-inventory", () => {
      // reserve inventory, return reservation response
      return ...;
    });
    const notified = call("notify", { reservation: reservation }).status;
    return Response.json({ notified: notified }, { status: 201 });
  });
}
```

